//! Compile-time generated, zero-allocation bilingual (`zh-CN` / `en`) i18n catalogue.
//!
//! Generated by `crates/pingdeck-desktop/build.rs` directly from repository-root
//! `locales/<area>/{en,zh-CN}.json` so:
//! - Every static UI string is compile-time checked via `Tr::new(lang).<area>().<key>(...)`,
//! - Zero raw JSON strings are parsed at runtime and zero `HashMap` heap allocations occur, and
//! - `cargo xtask check-i18n` enforces parity, placeholders, CJK spacing, and copy rules on the
//!   exact same files.

use pingdeck_core::model::settings::Language;

#[allow(dead_code, clippy::too_many_arguments)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/i18n_generated.rs"));
}

pub use generated::{
    Chat, Common, Environments, Exchange, Flows, History, Mock, Providers, Requests, Settings,
    Shared, Shell, Tr, Usage, Utility,
};

/// Creates a typed zero-cost i18n facade for `lang`.
#[must_use]
pub const fn tr(lang: Language) -> Tr {
    Tr::new(lang)
}

/// Looks up a dynamic key in the compile-time sorted catalogue (`O(log N)`, zero heap allocation).
#[must_use]
pub fn lookup(lang: Language, key: &str) -> Option<&'static str> {
    let idx = generated::ENTRIES
        .binary_search_by_key(&key, |entry| entry.0)
        .ok()?;
    let (_, zh, en) = generated::ENTRIES[idx];
    Some(match lang {
        Language::ZhCn => zh,
        Language::En => en,
    })
}

/// Looks up a dynamic localized string for `lang`, falling back to `key` if absent.
///
/// Prefer the compile-time typed `tr(lang).<area>().<key>(...)` methods for all static strings;
/// reserve `t` / `lookup` for genuinely runtime-computed keys (such as `set.f.tools.<name>.d`).
#[must_use]
pub fn t(lang: Language, key: &str) -> &str {
    lookup(lang, key).unwrap_or(key)
}

/// Looks up a dynamic localized string and substitutes `{name}` placeholders.
#[must_use]
pub fn t_args(lang: Language, key: &str, args: &[(&str, &str)]) -> String {
    let mut out = t(lang, key).to_owned();
    for (name, value) in args {
        let token = format!("{{{name}}}");
        out = out.replace(&token, value);
    }
    out
}

/// Looks up a dynamic `.one` / `.other` plural pair and substitutes `{count}`.
#[must_use]
pub fn t_plural(lang: Language, base_key: &str, count: usize) -> String {
    let suffix = if count == 1 { "one" } else { "other" };
    let full_key = format!("{base_key}.{suffix}");
    let count_str = count.to_string();
    t_args(lang, &full_key, &[("count", &count_str)])
}

/// Total number of compiled bilingual keys across all 14 locale areas.
#[must_use]
pub const fn total_keys() -> usize {
    generated::TOTAL_KEYS
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn compiled_typed_catalogue_and_dynamic_lookup_work() {
        assert!(total_keys() > 1000, "got {} keys", total_keys());
        assert_eq!(tr(Language::ZhCn).shell().nav_requests(), "请求");
        assert_eq!(tr(Language::En).shell().nav_requests(), "Requests");
        assert_eq!(lookup(Language::En, "shell.nav.requests"), Some("Requests"));
        assert_eq!(lookup(Language::En, "nonexistent.key.xyz"), None);
        assert_eq!(tr(Language::En).chat().trace_tool_calls(1), "1 tool call");
        assert_eq!(tr(Language::En).chat().trace_tool_calls(3), "3 tool calls");
        assert_eq!(
            tr(Language::En)
                .environments()
                .tab_analysis_unresolved_scan(),
            "Unresolved {{var}} Scan"
        );
        assert!(lookup(Language::ZhCn, "set.f.tools.get_request.d").is_some());
    }
}
